"""Reusable GPU engine for music visualizers (moderngl, OpenGL 4.1 core; works on Apple Silicon).

Building blocks
  Camera        look-at camera with roll, fov, focus distance and aperture (depth of field for lines)
  Lines         instanced 3D/HUD vector-line batch: glowing capsules, per-line circle-of-confusion blur
  Fluid         GPU stable-fluids solver (velocity + dye) with batched gaussian splats
  Engine        scene targets, procedural sky/stars/nebula background, full post chain, 8-bit readback

Typical frame
  eng.begin(slot, bg)            # clear scene target `slot` and draw the background
  eng.draw(lines3d, cam)         # additive glowing lines with DOF
  eng.draw(hud_lines, eng.hud_cam)
  eng.finish(post)               # composite (iris mask between slot 0/1), bloom, grade -> RGBA8
  frame = eng.read()             # bytes, top row first, RGB24 -> pipe to ffmpeg

NOTE (macOS): creating a GL context fails inside the Claude Code sandbox ("cannot choose pixel format").
Run render commands with the sandbox disabled.
"""
import numpy as np
import moderngl

# ---------------------------------------------------------------------------- math

def _norm(v):
    v = np.asarray(v, dtype=np.float64)
    return v / (np.linalg.norm(v) + 1e-12)


def look_at(eye, target, up=(0, 1, 0), roll=0.0):
    eye, target = np.asarray(eye, float), np.asarray(target, float)
    f = _norm(target - eye)
    up = _norm(up)
    if abs(np.dot(f, up)) > 0.999:
        up = _norm([0, 0, 1]) if abs(f[2]) < 0.9 else _norm([1, 0, 0])
    s = _norm(np.cross(f, up))
    u = np.cross(s, f)
    if roll:
        c, sn = np.cos(roll), np.sin(roll)
        s, u = c * s + sn * u, -sn * s + c * u
    M = np.eye(4)
    M[0, :3], M[1, :3], M[2, :3] = s, u, -f
    M[:3, 3] = -M[:3, :3] @ eye
    return M


def perspective(fovy_deg, aspect, near=0.05, far=5000.0):
    f = 1.0 / np.tan(np.radians(fovy_deg) / 2)
    M = np.zeros((4, 4))
    M[0, 0], M[1, 1] = f / aspect, f
    M[2, 2], M[2, 3] = (far + near) / (near - far), 2 * far * near / (near - far)
    M[3, 2] = -1
    return M


def ortho_px(W, H):
    """Pixel-space HUD camera: x in [-W/2, W/2], y in [-H/2, H/2], y up, z = -1."""
    M = np.eye(4)
    M[0, 0], M[1, 1] = 2.0 / W, 2.0 / H
    return M


def rot(axis, ang):
    axis = _norm(axis)
    x, y, z = axis
    c, s = np.cos(ang), np.sin(ang)
    C = 1 - c
    return np.array([[c + x * x * C, x * y * C - z * s, x * z * C + y * s],
                     [y * x * C + z * s, c + y * y * C, y * z * C - x * s],
                     [z * x * C - y * s, z * y * C + x * s, c + z * z * C]])


class Camera:
    def __init__(self, eye=(0, 0, 5), target=(0, 0, 0), up=(0, 1, 0), fov=60.0, roll=0.0,
                 focus=10.0, aperture=0.0, near=0.05, far=5000.0, aspect=16 / 9):
        self.eye, self.target, self.up = np.asarray(eye, float), np.asarray(target, float), up
        self.fov, self.roll, self.focus, self.aperture = fov, roll, focus, aperture
        self.near, self.far, self.aspect = near, far, aspect

    @property
    def view(self):
        return look_at(self.eye, self.target, self.up, self.roll)

    @property
    def proj(self):
        return perspective(self.fov, self.aspect, self.near, self.far)


def _m(M):
    return np.ascontiguousarray(M.T, dtype='f4').tobytes()


# ---------------------------------------------------------------------------- lines

class Lines:
    """Accumulates segments: a (N,3), b (N,3), color (N,3) HDR linear, width (N,2) = (pixels, world units)."""
    def __init__(self):
        self.parts = []

    def add(self, a, b, color, wpx=1.5, wworld=0.0):
        a = np.asarray(a, np.float32).reshape(-1, 3)
        b = np.asarray(b, np.float32).reshape(-1, 3)
        n = len(a)
        if n == 0:
            return
        col = np.broadcast_to(np.asarray(color, np.float32).reshape(-1, 3), (n, 3))
        wid = np.empty((n, 2), np.float32)
        wid[:, 0] = np.broadcast_to(np.asarray(wpx, np.float32), (n,))
        wid[:, 1] = np.broadcast_to(np.asarray(wworld, np.float32), (n,))
        self.parts.append(np.hstack([a, b, col, wid]))

    def polyline(self, pts, color, wpx=1.5, wworld=0.0, closed=False):
        pts = np.asarray(pts, np.float32)
        if closed:
            pts = np.vstack([pts, pts[:1]])
        if len(pts) < 2:
            return
        col = np.asarray(color, np.float32)
        if col.ndim == 2 and len(col) == len(pts):
            col = 0.5 * (col[:-1] + col[1:])
        w = np.asarray(wpx, np.float32)
        if w.ndim == 1 and len(w) == len(pts):
            w = 0.5 * (w[:-1] + w[1:])
        self.add(pts[:-1], pts[1:], col, w, wworld)

    def data(self):
        if not self.parts:
            return np.zeros((0, 11), np.float32)
        return np.ascontiguousarray(np.vstack(self.parts), dtype=np.float32)

    def __len__(self):
        return sum(len(p) for p in self.parts)


def circle_pts(center, radius, n=64, u=(1, 0, 0), v=(0, 1, 0), a0=0.0, a1=2 * np.pi, radii=None):
    th = np.linspace(a0, a1, n + 1)
    r = radius if radii is None else np.asarray(radii)
    u, v = np.asarray(u, float), np.asarray(v, float)
    return np.asarray(center, float) + (np.cos(th) * r)[:, None] * u + (np.sin(th) * r)[:, None] * v


# ---------------------------------------------------------------------------- shaders

FS_VS = """#version 410
out vec2 uv;
void main(){ vec2 p = vec2(float((gl_VertexID<<1)&2), float(gl_VertexID&2)); uv = p; gl_Position = vec4(p*2.0-1.0, 0.0, 1.0); }"""

LINE_VS = """#version 410
in vec3 a; in vec3 b; in vec3 col; in vec2 wid;
uniform mat4 V; uniform mat4 P; uniform vec2 res;
uniform float focus; uniform float aperture; uniform float maxcoc; uniform float fog; uniform float gain;
out vec2 v_p; out vec2 v_a; out vec2 v_b; out float v_r; out vec3 v_col;
void main(){
  vec4 va = V*vec4(a,1.0), vb = V*vec4(b,1.0);
  float nearz = 0.06;
  if (va.z > -nearz && vb.z > -nearz) { gl_Position = vec4(3.0,3.0,3.0,1.0); v_col=vec3(0); return; }
  if (va.z > -nearz) va = mix(va, vb, (-nearz - va.z)/(vb.z - va.z));
  if (vb.z > -nearz) vb = mix(vb, va, (-nearz - vb.z)/(va.z - vb.z));
  vec4 ca = P*va, cb = P*vb;
  vec2 sa = (ca.xy/ca.w*0.5+0.5)*res, sb = (cb.xy/cb.w*0.5+0.5)*res;
  float z = max(0.5*(-va.z - vb.z), nearz);
  float fpx = P[1][1]*0.5*res.y;
  bool persp = P[3][3] < 0.5;
  float w = wid.x + (persp ? wid.y*fpx/z : wid.y);
  w = max(w, 0.35);
  float coc = persp ? min(maxcoc, aperture*fpx*abs(1.0/z - 1.0/focus)) : 0.0;
  float r = sqrt(w*w + coc*coc);
  float energy = w/r;
  float atten = persp ? exp(-z*fog) * smoothstep(0.15, 1.2, z) : 1.0;
  v_col = col * energy * atten * gain;
  vec2 d = sb - sa; float L = length(d);
  vec2 dir = L > 1e-3 ? d/L : vec2(1.0,0.0);
  vec2 nrm = vec2(-dir.y, dir.x);
  float ext = r*2.6 + 1.5;
  int id = gl_VertexID;
  vec2 p = ((id==0||id==1) ? sa - dir*ext : sb + dir*ext) + nrm*((id==0||id==2) ? -ext : ext);
  v_p = p; v_a = sa; v_b = sb; v_r = r;
  gl_Position = vec4(p/res*2.0-1.0, 0.0, 1.0);
}"""

LINE_FS = """#version 410
in vec2 v_p; in vec2 v_a; in vec2 v_b; in float v_r; in vec3 v_col;
out vec4 o;
void main(){
  vec2 pa = v_p - v_a, ba = v_b - v_a;
  float h = clamp(dot(pa,ba)/max(dot(ba,ba),1e-6), 0.0, 1.0);
  float d = length(pa - ba*h);
  float s = v_r*0.62;
  float core = exp(-0.5*d*d/(s*s));
  float halo = exp(-d/(v_r*2.2+1.5))*0.12;
  o = vec4(v_col*(core+halo), 1.0);
}"""

BG_FS = """#version 410
in vec2 uv; out vec4 o;
uniform mat4 invVP; uniform vec3 sky_top; uniform vec3 sky_bot; uniform vec3 horizon; uniform float horizon_w;
uniform vec3 up; uniform float star_amt; uniform float star_twinkle; uniform float star_seed;
uniform sampler2D nebula; uniform float neb_amt; uniform vec2 neb_shift; uniform float neb_mask_sky;
uniform vec3 fogcol; uniform float fogamt;
float h31(vec3 p){ p = fract(p*0.3183099+vec3(0.71,0.113,0.419)); p *= 17.0; return fract(p.x*p.y*p.z*(p.x+p.y+p.z)); }
vec3 stars(vec3 d){
  vec3 a = abs(d); vec2 f; float face;
  if (a.x>a.y && a.x>a.z){ f = d.yz/a.x; face = sign(d.x); }
  else if (a.y>a.z){ f = d.xz/a.y; face = 2.0+sign(d.y); }
  else { f = d.xy/a.z; face = 4.0+sign(d.z); }
  vec3 acc = vec3(0);
  for (int l=0;l<2;l++){
    float sc = l==0 ? 90.0 : 210.0;
    vec2 g = f*sc; vec2 c = floor(g);
    for (int j=-1;j<=1;j++) for (int i=-1;i<=1;i++){
      vec2 cc = c+vec2(i,j);
      float hsh = h31(vec3(cc, face*13.0+float(l)*7.0+star_seed));
      if (hsh > 0.86){
        vec2 pos = cc + vec2(h31(vec3(cc,1.7+face)), h31(vec3(cc,9.1+face)));
        float dd = length(g-pos);
        float br = pow(h31(vec3(cc,3.3+face)), 3.0);
        float tw = 1.0 + star_twinkle*(h31(vec3(cc,5.5+face))-0.5)*2.0;
        acc += vec3(0.8,0.95,1.0)*br*tw*exp(-dd*dd*(l==0?5.0:9.0))*(l==0?1.0:0.5);
      }
    }
  }
  return acc;
}
void main(){
  vec4 p0 = invVP*vec4(uv*2.0-1.0, -1.0, 1.0), p1 = invVP*vec4(uv*2.0-1.0, 1.0, 1.0);
  vec3 d = normalize(p1.xyz/p1.w - p0.xyz/p0.w);
  float e = dot(d, up);
  vec3 c = mix(sky_bot, sky_top, smoothstep(-0.35, 0.6, e));
  c += horizon * exp(-abs(e)/max(horizon_w,1e-3));
  c += stars(d)*star_amt;
  vec3 neb = texture(nebula, uv + neb_shift).rgb;
  float skym = mix(1.0, smoothstep(-0.02, 0.12, e), neb_mask_sky);
  c += neb*neb_amt*skym;
  c = mix(c, fogcol, fogamt);
  o = vec4(c, 1.0);
}"""

COMPOSITE_FS = """#version 410
in vec2 uv; out vec4 o;
uniform sampler2D A; uniform sampler2D B; uniform float mix_mode; uniform vec2 iris_c; uniform float iris_r;
uniform vec3 edge_col; uniform float aspect; uniform float xfade;
void main(){
  vec3 a = texture(A, uv).rgb;
  vec3 c = a;
  if (mix_mode > 0.5){
    vec3 b = texture(B, uv).rgb;
    vec2 q = uv - iris_c; q.x *= aspect;
    float d = length(q) - iris_r;
    float m = 1.0 - smoothstep(-0.004, 0.004, d);
    c = mix(a, b, m) + edge_col*exp(-abs(d)*90.0);
    c = mix(c, b, xfade);
  }
  o = vec4(c, 1.0);
}"""

DOWN_FS = """#version 410
in vec2 uv; out vec4 o; uniform sampler2D src; uniform vec2 ts; uniform float threshold; uniform float knee;
vec3 s(vec2 p){ return texture(src, p).rgb; }
void main(){
  vec3 c = s(uv)*0.125;
  c += (s(uv+ts*vec2(-1,-1))+s(uv+ts*vec2(1,-1))+s(uv+ts*vec2(-1,1))+s(uv+ts*vec2(1,1)))*0.125;
  c += (s(uv+ts*vec2(-2,0))+s(uv+ts*vec2(2,0))+s(uv+ts*vec2(0,-2))+s(uv+ts*vec2(0,2)))*0.0625;
  c += (s(uv+ts*vec2(-2,-2))+s(uv+ts*vec2(2,-2))+s(uv+ts*vec2(-2,2))+s(uv+ts*vec2(2,2)))*0.03125;
  if (threshold > 0.0){
    float br = max(c.r, max(c.g, c.b));
    float rq = clamp(br - threshold + knee, 0.0, 2.0*knee); rq = rq*rq/(4.0*knee+1e-4);
    c *= max(rq, br - threshold)/max(br, 1e-4);
  }
  o = vec4(c, 1.0);
}"""

UP_FS = """#version 410
in vec2 uv; out vec4 o; uniform sampler2D src; uniform sampler2D base; uniform vec2 ts; uniform float w;
void main(){
  vec3 c = texture(src, uv).rgb*4.0;
  c += (texture(src, uv+ts*vec2(-1,0)).rgb+texture(src, uv+ts*vec2(1,0)).rgb+texture(src, uv+ts*vec2(0,-1)).rgb+texture(src, uv+ts*vec2(0,1)).rgb)*2.0;
  c += texture(src, uv+ts*vec2(-1,-1)).rgb+texture(src, uv+ts*vec2(1,-1)).rgb+texture(src, uv+ts*vec2(-1,1)).rgb+texture(src, uv+ts*vec2(1,1)).rgb;
  o = vec4(texture(base, uv).rgb + c/16.0*w, 1.0);
}"""

STREAK_FS = """#version 410
in vec2 uv; out vec4 o; uniform sampler2D src; uniform vec2 ts; uniform float step_;
void main(){
  vec3 c = vec3(0); float wsum = 0.0;
  for (int i=-4;i<=4;i++){ float w = exp(-float(i*i)/8.0); c += texture(src, uv+vec2(float(i)*step_*ts.x,0.0)).rgb*w; wsum += w; }
  o = vec4(c/wsum, 1.0);
}"""

FINAL_FS = """#version 410
in vec2 uv; out vec4 o;
uniform sampler2D scene; uniform sampler2D bloom; uniform sampler2D streak; uniform sampler2D blurred;
uniform float aspect; uniform float frame;
uniform float bloom_amt; uniform float streak_amt; uniform vec3 streak_tint;
uniform float exposure; uniform float flash; uniform vec3 flash_col;
uniform float ca; uniform float barrel; uniform float zoomblur; uniform vec2 center;
uniform vec4 shocks[4];        // xy center (uv), z radius (in height units), w strength
uniform float kaleido; uniform float kaleido_n; uniform float kaleido_rot;
uniform float defocus; uniform float saturation; uniform vec3 lift; uniform vec3 gain; uniform float contrast;
uniform float vignette; uniform float scan; uniform float grain; uniform float fade;
uniform vec3 tint; uniform float tint_amt;
float h12(vec2 p){ vec3 p3 = fract(vec3(p.xyx)*0.1031); p3 += dot(p3, p3.yzx+33.33); return fract((p3.x+p3.y)*p3.z); }
vec3 aces(vec3 x){ return clamp((x*(2.51*x+0.03))/(x*(2.43*x+0.59)+0.14), 0.0, 1.0); }
vec3 to_srgb(vec3 c){ return mix(12.92*c, 1.055*pow(c, vec3(1.0/2.4))-0.055, step(0.0031308, c)); }
vec2 distort(vec2 p){
  vec2 q = p - center; q.x *= aspect;
  // kaleidoscope fold
  if (kaleido > 0.0){
    float r = length(q), a = atan(q.y, q.x) + kaleido_rot;
    float seg = 6.2831853/kaleido_n;
    float af = abs(mod(a, seg) - seg*0.5) - kaleido_rot;
    vec2 kq = r*vec2(cos(af), sin(af));
    q = mix(q, kq, kaleido);
  }
  float r2 = dot(q,q);
  q *= 1.0 + barrel*r2;
  for (int i=0;i<4;i++){
    vec2 d = q - (shocks[i].xy - center)*vec2(aspect,1.0);
    float L = length(d);
    float band = exp(-pow((L - shocks[i].z)/0.035, 2.0));
    q -= (L > 1e-4 ? d/L : vec2(0)) * band * shocks[i].w * 0.045;
  }
  q.x /= aspect;
  return q + center;
}
void main(){
  vec2 p = vec2(uv.x, 1.0-uv.y);   // flip so readback is top row first
  vec2 dp = distort(p);
  vec2 dir = dp - center;
  vec3 c = vec3(0);
  if (zoomblur > 0.001){
    float wsum = 0.0;
    for (int i=0;i<10;i++){
      float k = 1.0 - zoomblur*float(i)/9.0*0.12;
      float w = 1.0 - float(i)/12.0;
      vec2 sp = center + dir*k;
      c += vec3(texture(scene, sp + dir*ca*0.012).r, texture(scene, sp).g, texture(scene, sp - dir*ca*0.012).b)*w; wsum += w;
    }
    c /= wsum;
  } else {
    c = vec3(texture(scene, dp + dir*ca*0.012).r, texture(scene, dp).g, texture(scene, dp - dir*ca*0.012).b);
  }
  vec3 bl = texture(bloom, dp).rgb;
  c = mix(c, texture(blurred, dp).rgb, defocus);
  c += bl*bloom_amt;
  c += texture(streak, dp).rgb*streak_amt*streak_tint;
  c *= exposure;
  c += flash_col*flash;
  c = mix(c, c*tint, tint_amt);
  c = aces(c);
  float lum = dot(c, vec3(0.2126,0.7152,0.0722));
  c = mix(vec3(lum), c, saturation);
  c = pow(max(c, 0.0), vec3(contrast));
  c = c*gain + lift*(1.0-c);
  vec2 vq = (p-0.5)*vec2(aspect,1.0);
  c *= 1.0 - vignette*smoothstep(0.35, 1.05, length(vq));
  c *= 1.0 - scan*(0.5+0.5*cos(p.y*3.14159*540.0*2.0));
  c = clamp(c, 0.0, 1.0);
  c = to_srgb(c);
  float g = h12(gl_FragCoord.xy + frame*37.13) + h12(gl_FragCoord.xy*1.37 + frame*11.7) - 1.0;
  c += g*grain;
  c *= 1.0 - fade;
  c += (h12(gl_FragCoord.xy + frame) - h12(gl_FragCoord.yx*0.73 + frame*1.3))/255.0;   // TPDF dither
  o = vec4(clamp(c, 0.0, 1.0), 1.0);
}"""

# fluid ---------------------------------------------------------------
ADVECT_FS = """#version 410
in vec2 uv; out vec4 o; uniform sampler2D vel; uniform sampler2D src; uniform vec2 ts; uniform float dt; uniform float diss;
void main(){ vec2 c = uv - dt*texture(vel, uv).xy*ts; o = texture(src, c)/(1.0+diss*dt); }"""
DIV_FS = """#version 410
in vec2 uv; out vec4 o; uniform sampler2D vel; uniform vec2 ts;
void main(){
  float L = texture(vel, uv-vec2(ts.x,0)).x, R = texture(vel, uv+vec2(ts.x,0)).x;
  float B = texture(vel, uv-vec2(0,ts.y)).y, T = texture(vel, uv+vec2(0,ts.y)).y;
  vec2 C = texture(vel, uv).xy;
  if (uv.x-ts.x < 0.0) L = -C.x; if (uv.x+ts.x > 1.0) R = -C.x; if (uv.y-ts.y < 0.0) B = -C.y; if (uv.y+ts.y > 1.0) T = -C.y;
  o = vec4(0.5*(R-L+T-B), 0, 0, 1);
}"""
CURL_FS = """#version 410
in vec2 uv; out vec4 o; uniform sampler2D vel; uniform vec2 ts;
void main(){
  float L = texture(vel, uv-vec2(ts.x,0)).y, R = texture(vel, uv+vec2(ts.x,0)).y;
  float B = texture(vel, uv-vec2(0,ts.y)).x, T = texture(vel, uv+vec2(0,ts.y)).x;
  o = vec4(0.5*(R-L-T+B), 0, 0, 1);
}"""
VORT_FS = """#version 410
in vec2 uv; out vec4 o; uniform sampler2D vel; uniform sampler2D curl; uniform vec2 ts; uniform float strength; uniform float dt;
void main(){
  float L = texture(curl, uv-vec2(ts.x,0)).x, R = texture(curl, uv+vec2(ts.x,0)).x;
  float B = texture(curl, uv-vec2(0,ts.y)).x, T = texture(curl, uv+vec2(0,ts.y)).x, C = texture(curl, uv).x;
  vec2 f = 0.5*vec2(abs(T)-abs(B), abs(R)-abs(L)); f /= length(f)+1e-4; f *= strength*C; f.y *= -1.0;
  vec2 v = texture(vel, uv).xy + f*dt;
  o = vec4(clamp(v, -2000.0, 2000.0), 0, 1);
}"""
PRESS_FS = """#version 410
in vec2 uv; out vec4 o; uniform sampler2D pres; uniform sampler2D div; uniform vec2 ts;
void main(){
  float L = texture(pres, uv-vec2(ts.x,0)).x, R = texture(pres, uv+vec2(ts.x,0)).x;
  float B = texture(pres, uv-vec2(0,ts.y)).x, T = texture(pres, uv+vec2(0,ts.y)).x;
  o = vec4((L+R+B+T-texture(div, uv).x)*0.25, 0, 0, 1);
}"""
GRAD_FS = """#version 410
in vec2 uv; out vec4 o; uniform sampler2D pres; uniform sampler2D vel; uniform vec2 ts;
void main(){
  float L = texture(pres, uv-vec2(ts.x,0)).x, R = texture(pres, uv+vec2(ts.x,0)).x;
  float B = texture(pres, uv-vec2(0,ts.y)).x, T = texture(pres, uv+vec2(0,ts.y)).x;
  o = vec4(texture(vel, uv).xy - vec2(R-L, T-B), 0, 1);
}"""
SCALE_FS = """#version 410
in vec2 uv; out vec4 o; uniform sampler2D src; uniform float k;
void main(){ o = texture(src, uv)*k; }"""
SPLAT_FS = """#version 410
in vec2 uv; out vec4 o; uniform sampler2D src; uniform float aspect; uniform int n;
uniform vec4 pt[32];    // xy uv, z radius, w unused
uniform vec4 val[32];   // rgb or xy velocity
void main(){
  vec4 base = texture(src, uv);
  vec3 add = vec3(0);
  for (int i=0;i<32;i++){ if (i>=n) break;
    vec2 p = uv - pt[i].xy; p.x *= aspect;
    add += exp(-dot(p,p)/pt[i].z)*val[i].rgb; }
  o = vec4(base.rgb + add, 1.0);
}"""


class Fluid:
    def __init__(self, ctx, sim=(320, 180), dye=(960, 540), vao_factory=None):
        self.ctx = ctx
        self.sim, self.dye = sim, dye
        mk = lambda size: ctx.texture(size, 4, dtype='f2')
        def pair(size):
            ts = [mk(size), mk(size)]
            for t in ts:
                t.repeat_x = t.repeat_y = False
                t.filter = (moderngl.LINEAR, moderngl.LINEAR)
            return ts, [ctx.framebuffer([t]) for t in ts]
        self.vel, self.vel_fb = pair(sim)
        self.dyet, self.dye_fb = pair(dye)
        self.pres, self.pres_fb = pair(sim)
        self.divt = mk(sim); self.div_fb = ctx.framebuffer([self.divt])
        self.curlt = mk(sim); self.curl_fb = ctx.framebuffer([self.curlt])
        for fb in self.vel_fb + self.dye_fb + self.pres_fb + [self.div_fb, self.curl_fb]:
            fb.use(); ctx.clear(0, 0, 0, 1)
        P = lambda fs: ctx.program(vertex_shader=FS_VS, fragment_shader=fs)
        self.p = {k: P(v) for k, v in dict(adv=ADVECT_FS, div=DIV_FS, curl=CURL_FS, vort=VORT_FS, pres=PRESS_FS,
                                           grad=GRAD_FS, scale=SCALE_FS, splat=SPLAT_FS).items()}
        self.vao = {k: ctx.vertex_array(p, []) for k, p in self.p.items()}
        self.vi = self.di = self.pi = 0
        self.pending_v, self.pending_d = [], []

    def _run(self, name, fb, size, **tex_and_uniforms):
        prog = self.p[name]
        unit = 0
        for k, v in tex_and_uniforms.items():
            if isinstance(v, moderngl.Texture):
                v.use(unit); prog[k].value = unit; unit += 1
            elif k in prog:
                prog[k].value = v
        fb.use()
        self.ctx.viewport = (0, 0, *size)
        self.vao[name].render(moderngl.TRIANGLES, vertices=3)

    def splat(self, x, y, dx, dy, color, radius=0.002):
        """x,y in uv (0..1, y up). dx,dy velocity in sim texels/s. color = dye rgb (HDR)."""
        self.pending_v.append((x, y, radius, dx, dy))
        self.pending_d.append((x, y, radius, *color))

    def _flush(self, which):
        items = self.pending_v if which == 'v' else self.pending_d
        size = self.sim if which == 'v' else self.dye
        aspect = size[0] / size[1]
        prog = self.p['splat']
        for i in range(0, len(items), 32):
            chunk = items[i:i + 32]
            pts = np.zeros((32, 4), 'f4'); vals = np.zeros((32, 4), 'f4')
            for j, it in enumerate(chunk):
                pts[j, :3] = it[:3]
                vals[j, :len(it) - 3] = it[3:]
            prog['pt'].write(pts.tobytes()); prog['val'].write(vals.tobytes()); prog['n'].value = len(chunk)
            if which == 'v':
                self._run('splat', self.vel_fb[1 - self.vi], size, src=self.vel[self.vi], aspect=aspect); self.vi = 1 - self.vi
            else:
                self._run('splat', self.dye_fb[1 - self.di], size, src=self.dyet[self.di], aspect=aspect); self.di = 1 - self.di
        items.clear()

    def step(self, dt=1 / 60, curl=25.0, vel_diss=0.4, dye_diss=0.9, iters=22, pressure_keep=0.8):
        ctx = self.ctx
        ctx.disable(moderngl.BLEND)
        ts = (1 / self.sim[0], 1 / self.sim[1])
        self._flush('v'); self._flush('d')
        self._run('curl', self.curl_fb, self.sim, vel=self.vel[self.vi], ts=ts)
        self._run('vort', self.vel_fb[1 - self.vi], self.sim, vel=self.vel[self.vi], curl=self.curlt, ts=ts, strength=curl, dt=dt); self.vi = 1 - self.vi
        self._run('div', self.div_fb, self.sim, vel=self.vel[self.vi], ts=ts)
        self._run('scale', self.pres_fb[1 - self.pi], self.sim, src=self.pres[self.pi], k=pressure_keep); self.pi = 1 - self.pi
        for _ in range(iters):
            self._run('pres', self.pres_fb[1 - self.pi], self.sim, pres=self.pres[self.pi], div=self.divt, ts=ts); self.pi = 1 - self.pi
        self._run('grad', self.vel_fb[1 - self.vi], self.sim, pres=self.pres[self.pi], vel=self.vel[self.vi], ts=ts); self.vi = 1 - self.vi
        self._run('adv', self.vel_fb[1 - self.vi], self.sim, vel=self.vel[self.vi], src=self.vel[self.vi], ts=ts, dt=dt, diss=vel_diss); self.vi = 1 - self.vi
        self._run('adv', self.dye_fb[1 - self.di], self.dye, vel=self.vel[self.vi], src=self.dyet[self.di], ts=ts, dt=dt, diss=dye_diss); self.di = 1 - self.di

    @property
    def dye_tex(self):
        return self.dyet[self.di]


# ---------------------------------------------------------------------------- engine

DEFAULT_BG = dict(sky_top=(0.0, 0.0, 0.0), sky_bot=(0.0, 0.0, 0.0), horizon=(0, 0, 0), horizon_w=0.05, up=(0, 1, 0),
                  star_amt=0.0, star_twinkle=0.0, star_seed=0.0, neb_amt=0.0, neb_shift=(0, 0), neb_mask_sky=0.0,
                  fogcol=(0, 0, 0), fogamt=0.0)
DEFAULT_POST = dict(bloom_amt=0.8, streak_amt=0.0, streak_tint=(0.6, 0.8, 1.0), exposure=1.0, flash=0.0, flash_col=(1, 1, 1),
                    ca=0.0, barrel=0.0, zoomblur=0.0, center=(0.5, 0.5), shocks=(), kaleido=0.0, kaleido_n=6.0, kaleido_rot=0.0,
                    defocus=0.0, saturation=1.0, lift=(0, 0, 0), gain=(1, 1, 1), contrast=1.0, vignette=0.35, scan=0.0,
                    grain=0.012, fade=0.0, tint=(1, 1, 1), tint_amt=0.0, bloom_threshold=0.9, bloom_knee=0.5,
                    mix_mode=0.0, iris_c=(0.5, 0.5), iris_r=0.0, edge_col=(0, 0, 0), xfade=0.0)


class Engine:
    def __init__(self, W=1920, H=1080, fluid=True, fluid_sim=(320, 180), fluid_dye=(960, 540), max_lines=400_000):
        self.W, self.H = W, H
        ctx = self.ctx = moderngl.create_standalone_context(require=410)
        hdr = lambda w, h: ctx.texture((w, h), 4, dtype='f2')
        self.scene = [hdr(W, H), hdr(W, H)]
        for t in self.scene:
            t.repeat_x = t.repeat_y = False
        self.scene_fb = [ctx.framebuffer([t]) for t in self.scene]
        self.comp = hdr(W, H); self.comp.repeat_x = self.comp.repeat_y = False
        self.comp_fb = ctx.framebuffer([self.comp])
        # bloom mip chain from half res
        self.mips, self.mip_fb, self.ups, self.up_fb = [], [], [], []
        w, h = W // 2, H // 2
        for _ in range(6):
            t = hdr(w, h); t.repeat_x = t.repeat_y = False
            self.mips.append(t); self.mip_fb.append(ctx.framebuffer([t]))
            u = hdr(w, h); u.repeat_x = u.repeat_y = False
            self.ups.append(u); self.up_fb.append(ctx.framebuffer([u]))
            w, h = max(1, w // 2), max(1, h // 2)
        self.streak = [hdr(W // 4, H // 4) for _ in range(2)]
        for t in self.streak:
            t.repeat_x = t.repeat_y = False
        self.streak_fb = [ctx.framebuffer([t]) for t in self.streak]
        self.out = ctx.texture((W, H), 4)
        self.out_fb = ctx.framebuffer([self.out])
        P = lambda vs, fs: ctx.program(vertex_shader=vs, fragment_shader=fs)
        self.p_line = P(LINE_VS, LINE_FS)
        self.p_bg = P(FS_VS, BG_FS)
        self.p_comp = P(FS_VS, COMPOSITE_FS)
        self.p_down = P(FS_VS, DOWN_FS)
        self.p_up = P(FS_VS, UP_FS)
        self.p_streak = P(FS_VS, STREAK_FS)
        self.p_final = P(FS_VS, FINAL_FS)
        self.fsvao = {k: ctx.vertex_array(p, []) for k, p in
                      dict(bg=self.p_bg, comp=self.p_comp, down=self.p_down, up=self.p_up, streak=self.p_streak, final=self.p_final).items()}
        self.max_lines = max_lines
        self.lbuf = ctx.buffer(reserve=max_lines * 44)
        self.lvao = ctx.vertex_array(self.p_line, [(self.lbuf, '3f 3f 3f 2f/i', 'a', 'b', 'col', 'wid')])
        self.fluid = Fluid(ctx, fluid_sim, fluid_dye) if fluid else None
        self.black = ctx.texture((4, 4), 4, dtype='f2')
        self.hud_cam = Camera()
        self.hud_view, self.hud_proj = np.eye(4), ortho_px(W, H)
        self.frame = 0

    # --------------------------------------------------------------- helpers
    def _uniforms(self, prog, d):
        for k, v in d.items():
            if k in prog:
                u = prog[k]
                if isinstance(v, (tuple, list, np.ndarray)):
                    u.value = tuple(float(x) for x in np.asarray(v).ravel())
                else:
                    u.value = float(v) if not isinstance(v, int) or u.dimension != 1 else v

    def _fs(self, name, fb, size, textures=(), **uni):
        prog = {'bg': self.p_bg, 'comp': self.p_comp, 'down': self.p_down, 'up': self.p_up, 'streak': self.p_streak, 'final': self.p_final}[name]
        for i, (k, t) in enumerate(textures):
            t.use(i); prog[k].value = i
        self._uniforms(prog, uni)
        fb.use(); self.ctx.viewport = (0, 0, *size)
        self.fsvao[name].render(moderngl.TRIANGLES, vertices=3)

    # --------------------------------------------------------------- scene
    def begin(self, slot, bg=None, cam=None):
        """Clear scene target `slot` and draw the background (sky, stars, fluid nebula)."""
        ctx = self.ctx
        ctx.disable(moderngl.BLEND)
        b = dict(DEFAULT_BG); b.update(bg or {})
        cam = cam or Camera()
        VP = cam.proj @ cam.view
        neb = self.fluid.dye_tex if self.fluid is not None else self.black
        self._fs('bg', self.scene_fb[slot], (self.W, self.H), textures=[('nebula', neb)], invVP=np.linalg.inv(VP).T.ravel(), **b)
        self.slot = slot

    def draw(self, lines, cam, hud=False, gain=1.0, fog=0.0, maxcoc=48.0):
        data = lines.data() if isinstance(lines, Lines) else lines
        n = len(data)
        if n == 0:
            return
        if n > self.max_lines:
            data = data[:self.max_lines]; n = self.max_lines
        ctx = self.ctx
        self.lbuf.orphan(self.max_lines * 44)
        self.lbuf.write(data.tobytes())
        p = self.p_line
        if hud:
            p['V'].write(_m(self.hud_view)); p['P'].write(_m(self.hud_proj))
            p['aperture'].value = 0.0; p['focus'].value = 1.0; p['fog'].value = 0.0
        else:
            p['V'].write(_m(cam.view)); p['P'].write(_m(cam.proj))
            p['aperture'].value = float(cam.aperture); p['focus'].value = float(cam.focus); p['fog'].value = float(fog)
        p['res'].value = (float(self.W), float(self.H))
        p['maxcoc'].value = float(maxcoc); p['gain'].value = float(gain)
        self.scene_fb[self.slot].use(); ctx.viewport = (0, 0, self.W, self.H)
        ctx.enable(moderngl.BLEND); ctx.blend_func = (moderngl.ONE, moderngl.ONE)
        self.lvao.render(moderngl.TRIANGLE_STRIP, vertices=4, instances=n)
        ctx.disable(moderngl.BLEND)

    # --------------------------------------------------------------- post
    def finish(self, post=None):
        q = dict(DEFAULT_POST); q.update(post or {})
        W, H = self.W, self.H
        self._fs('comp', self.comp_fb, (W, H), textures=[('A', self.scene[0]), ('B', self.scene[1])],
                 mix_mode=q['mix_mode'], iris_c=q['iris_c'], iris_r=q['iris_r'], edge_col=q['edge_col'], aspect=W / H, xfade=q['xfade'])
        # bloom
        src = self.comp
        for i, (t, fb) in enumerate(zip(self.mips, self.mip_fb)):
            self._fs('down', fb, t.size, textures=[('src', src)], ts=(1 / src.size[0], 1 / src.size[1]),
                     threshold=q['bloom_threshold'] if i == 0 else 0.0, knee=q['bloom_knee'])
            src = t
        up = self.mips[-1]
        for i in range(len(self.mips) - 2, -1, -1):
            self._fs('up', self.up_fb[i], self.mips[i].size, textures=[('src', up), ('base', self.mips[i])],
                     ts=(1 / up.size[0], 1 / up.size[1]), w=1.0)
            up = self.ups[i]
        bloom = up
        # anamorphic streak from mip1 (quarter res)
        s_in = self.mips[1]
        a, b = 0, 1
        self._fs('streak', self.streak_fb[a], self.streak[a].size, textures=[('src', s_in)], ts=(1 / s_in.size[0], 1 / s_in.size[1]), step_=2.0)
        for st in (6.0, 18.0, 40.0):
            self._fs('streak', self.streak_fb[b], self.streak[b].size, textures=[('src', self.streak[a])],
                     ts=(1 / self.streak[a].size[0], 1 / self.streak[a].size[1]), step_=st)
            a, b = b, a
        shocks = np.zeros((4, 4), 'f4')
        for i, s in enumerate(list(q['shocks'])[:4]):
            shocks[i] = s
        self.p_final['shocks'].write(shocks.tobytes())
        uni = {k: q[k] for k in ['bloom_amt', 'streak_amt', 'streak_tint', 'exposure', 'flash', 'flash_col', 'ca', 'barrel', 'zoomblur', 'center',
                                 'kaleido', 'kaleido_n', 'kaleido_rot', 'defocus', 'saturation', 'lift', 'gain', 'contrast', 'vignette',
                                 'scan', 'grain', 'fade', 'tint', 'tint_amt']}
        self._fs('final', self.out_fb, (W, H), textures=[('scene', self.comp), ('bloom', bloom), ('streak', self.streak[a]), ('blurred', self.ups[1])],
                 aspect=W / H, frame=float(self.frame % 9973), **uni)
        self.frame += 1

    def read(self):
        return self.out_fb.read(components=3, alignment=1)

