"""Reusable GPU engine for music visualizers (moderngl, OpenGL 4.1 core; works on Apple Silicon).

Building blocks
  Camera        look-at camera with roll, fov, focus distance and aperture (depth of field for lines)
  Lines         instanced 3D/HUD vector-line batch: glowing capsules, per-line circle-of-confusion blur
  Fluid         GPU stable-fluids solver (velocity + dye) with batched gaussian splats
  Engine        scene targets, procedural sky/stars/nebula background, full post chain, 8-bit readback

Typical frame
  eng.begin(slot, bg)            # clear scene target `slot` and draw the background
  eng.draw(lines3d, cam)         # additive glowing lines with DOF
  eng.draw(hud_lines, eng.hud_cam)
  eng.finish(post)               # composite (iris mask between slot 0/1), bloom, grade -> RGBA8
  frame = eng.read()             # bytes, top row first, RGB24 -> pipe to ffmpeg

NOTE (macOS): creating a GL context fails inside the Claude Code sandbox ("cannot choose pixel format").
Run render commands with the sandbox disabled.
"""
import numpy as np
import moderngl

# ---------------------------------------------------------------------------- math

def _norm(v):
    v = np.asarray(v, dtype=np.float64)
    return v / (np.linalg.norm(v) + 1e-12)


def look_at(eye, target, up=(0, 1, 0), roll=0.0):
    eye, target = np.asarray(eye, float), np.asarray(target, float)
    f = _norm(target - eye)
    up = _norm(up)
    if abs(np.dot(f, up)) > 0.999:
        up = _norm([0, 0, 1]) if abs(f[2]) < 0.9 else _norm([1, 0, 0])
    s = _norm(np.cross(f, up))
    u = np.cross(s, f)
    if roll:
        c, sn = np.cos(roll), np.sin(roll)
        s, u = c * s + sn * u, -sn * s + c * u
    M = np.eye(4)
    M[0, :3], M[1, :3], M[2, :3] = s, u, -f
    M[:3, 3] = -M[:3, :3] @ eye
    return M


def perspective(fovy_deg, aspect, near=0.05, far=5000.0):
    f = 1.0 / np.tan(np.radians(fovy_deg) / 2)
    M = np.zeros((4, 4))
    M[0, 0], M[1, 1] = f / aspect, f
    M[2, 2], M[2, 3] = (far + near) / (near - far), 2 * far * near / (near - far)
    M[3, 2] = -1
    return M


def ortho_px(W, H):
    """Pixel-space HUD camera: x in [-W/2, W/2], y in [-H/2, H/2], y up, z = -1."""
    M = np.eye(4)
    M[0, 0], M[1, 1] = 2.0 / W, 2.0 / H
    return M


def rot(axis, ang):
    axis = _norm(axis)
    x, y, z = axis
    c, s = np.cos(ang), np.sin(ang)
    C = 1 - c
    return np.array([[c + x * x * C, x * y * C - z * s, x * z * C + y * s],
                     [y * x * C + z * s, c + y * y * C, y * z * C - x * s],
                     [z * x * C - y * s, z * y * C + x * s, c + z * z * C]])


class Camera:
    def __init__(self, eye=(0, 0, 5), target=(0, 0, 0), up=(0, 1, 0), fov=60.0, roll=0.0,
                 focus=10.0, aperture=0.0, near=0.05, far=5000.0, aspect=16 / 9):
        self.eye, self.target, self.up = np.asarray(eye, float), np.asarray(target, float), up
        self.fov, self.roll, self.focus, self.aperture = fov, roll, focus, aperture
        self.near, self.far, self.aspect = near, far, aspect

    @property
    def view(self):
        return look_at(self.eye, self.target, self.up, self.roll)

    @property
    def proj(self):
        return perspective(self.fov, self.aspect, self.near, self.far)


def _m(M):
    return np.ascontiguousarray(M.T, dtype='f4').tobytes()


# ---------------------------------------------------------------------------- lines

class Lines:
    """Accumulates segments: a (N,3), b (N,3), color (N,3) HDR linear, width (N,2) = (pixels, world units)."""
    def __init__(self):
        self.parts = []

    def add(self, a, b, color, wpx=1.5, wworld=0.0):
        a = np.asarray(a, np.float32).reshape(-1, 3)
        b = np.asarray(b, np.float32).reshape(-1, 3)
        n = len(a)
        if n == 0:
            return
        col = np.broadcast_to(np.asarray(color, np.float32).reshape(-1, 3), (n, 3))
        wid = np.empty((n, 2), np.float32)
        wid[:, 0] = np.broadcast_to(np.asarray(wpx, np.float32), (n,))
        wid[:, 1] = np.broadcast_to(np.asarray(wworld, np.float32), (n,))
        self.parts.append(np.hstack([a, b, col, wid]))

    def polyline(self, pts, color, wpx=1.5, wworld=0.0, closed=False):
        pts = np.asarray(pts, np.float32)
        if closed:
            pts = np.vstack([pts, pts[:1]])
        if len(pts) < 2:
            return
        col = np.asarray(color, np.float32)
        if col.ndim == 2 and len(col) == len(pts):
            col = 0.5 * (col[:-1] + col[1:])
        w = np.asarray(wpx, np.float32)
        if w.ndim == 1 and len(w) == len(pts):
            w = 0.5 * (w[:-1] + w[1:])
        self.add(pts[:-1], pts[1:], col, w, wworld)

    def data(self):
        if not self.parts:
            return np.zeros((0, 11), np.float32)
        return np.ascontiguousarray(np.vstack(self.parts), dtype=np.float32)

    def __len__(self):
        return sum(len(p) for p in self.parts)


def circle_pts(center, radius, n=64, u=(1, 0, 0), v=(0, 1, 0), a0=0.0, a1=2 * np.pi, radii=None):
    th = np.linspace(a0, a1, n + 1)
    r = radius if radii is None else np.asarray(radii)
    u, v = np.asarray(u, float), np.asarray(v, float)
    return np.asarray(center, float) + (np.cos(th) * r)[:, None] * u + (np.sin(th) * r)[:, None] * v


