ADVECT_FS = """#version 410
in vec2 uv; out vec4 o; uniform sampler2D vel; uniform sampler2D src; uniform vec2 ts; uniform float dt; uniform float diss;
void main(){ vec2 c = uv - dt*texture(vel, uv).xy*ts; o = texture(src, c)/(1.0+diss*dt); }"""
DIV_FS = """#version 410
in vec2 uv; out vec4 o; uniform sampler2D vel; uniform vec2 ts;
void main(){
  float L = texture(vel, uv-vec2(ts.x,0)).x, R = texture(vel, uv+vec2(ts.x,0)).x;
  float B = texture(vel, uv-vec2(0,ts.y)).y, T = texture(vel, uv+vec2(0,ts.y)).y;
  vec2 C = texture(vel, uv).xy;
  if (uv.x-ts.x < 0.0) L = -C.x; if (uv.x+ts.x > 1.0) R = -C.x; if (uv.y-ts.y < 0.0) B = -C.y; if (uv.y+ts.y > 1.0) T = -C.y;
  o = vec4(0.5*(R-L+T-B), 0, 0, 1);
}"""
CURL_FS = """#version 410
in vec2 uv; out vec4 o; uniform sampler2D vel; uniform vec2 ts;
void main(){
  float L = texture(vel, uv-vec2(ts.x,0)).y, R = texture(vel, uv+vec2(ts.x,0)).y;
  float B = texture(vel, uv-vec2(0,ts.y)).x, T = texture(vel, uv+vec2(0,ts.y)).x;
